oxy_webhelp_navlinks = {"hadr_overview-d39536e6345":{"topics":[{"title":"High Availability prerequisites","shortdesc":"<p class=\"shortdesc\">Information about the requirements, supported configurations, and limitations for         High Availability.<\/p>","href":"hadr\/hadr_prerequisites.html","attributes":{"data-id":"hadr_prerequisites"},"menu":{"hasChildren":false},"tocID":"hadr_prerequisites-d39536e6356","topics":[]},{"title":"High Availability key concepts","shortdesc":"<p class=\"shortdesc\">High Availability Policies use the following key concepts to manage failovers and         failbacks.<\/p>","href":"hadr\/hadr_key_concepts.html","attributes":{"data-id":"hadr_key_concepts"},"menu":{"hasChildren":false},"tocID":"hadr_key_concepts-d39536e6367","topics":[]},{"title":"How failover works","shortdesc":"<p class=\"shortdesc\">High Availability Policies follow a defined sequence of actions to manage data         protection during a failover.<\/p>","href":"hadr\/how_failover_works.html","attributes":{"data-id":"how_failover_works"},"menu":{"hasChildren":false},"tocID":"how_failover_works-d39536e6378","topics":[]},{"title":"Preparing to create an HA Policy","shortdesc":"<p class=\"shortdesc\">Prepare the clusters and hosts that you want to manage with the HA         Policy.<\/p>","href":"hadr\/preparing_create_ha_policy.html","attributes":{"data-id":"preparing_create_ha_policy"},"menu":{"hasChildren":false},"tocID":"preparing_create_ha_policy-d39536e6389","topics":[]},{"title":"Creating HA Policies","shortdesc":"<p class=\"shortdesc\">Create HA Policies to define the primary and secondary Rubrik cluster pair, hosts,         and the archival locations that participate in a failover.<\/p>","href":"hadr\/creating_ha_policies.html","attributes":{"data-id":"creating_ha_policies"},"menu":{"hasChildren":false},"tocID":"creating_ha_policies-d39536e6400","topics":[]},{"title":"Creating HA SLA Domains","shortdesc":"<p class=\"shortdesc\">Create an HA SLA Domain with bidirectional replication to protect workloads with an         HA Policy.<\/p>","href":"hadr\/creating_ha_sla_domains.html","attributes":{"data-id":"creating_ha_sla_domains"},"menu":{"hasChildren":false},"tocID":"creating_ha_sla_domains-d39536e6411","topics":[]},{"title":"Protecting workloads with an HA Policy","shortdesc":"<p class=\"shortdesc\">Assign a High Availability SLA Domain to the protected workloads that you want to         manage with an HA Policy.<\/p>","href":"hadr\/protecting_workloads_ha_policy.html","attributes":{"data-id":"protecting_workloads_ha_policy"},"menu":{"hasChildren":false},"tocID":"protecting_workloads_ha_policy-d39536e6422","topics":[]},{"title":"Performing a failover","shortdesc":"<p class=\"shortdesc\">Start a manual failover to transfer backup and recovery operations from the primary         Rubrik cluster to the secondary Rubrik cluster in a High Availability Policy.<\/p>","href":"hadr\/performing_failover.html","attributes":{"data-id":"performing_failover"},"menu":{"hasChildren":false},"tocID":"performing_failover-d39536e6433","topics":[]},{"title":"Performing a failback","shortdesc":"<p class=\"shortdesc\">Start a failback to restore backup and recovery operations from the secondary Rubrik         cluster to the original primary Rubrik cluster after a failover.<\/p>","href":"hadr\/performing_failback.html","attributes":{"data-id":"performing_failback"},"menu":{"hasChildren":false},"tocID":"performing_failback-d39536e6444","topics":[]},{"title":"HA Policy management","shortdesc":"<p class=\"shortdesc\">You can add or remove members from an HA Policy, edit HA SLA Domains, and delete HA         Policies that are no longer needed.<\/p>","href":"hadr\/ha_policy_management.html","attributes":{"data-id":"ha_policy_management"},"menu":{"hasChildren":false},"tocID":"ha_policy_management-d39536e6455","next":"ha_policy_management-d39536e6455"}]}};